package io.joshuasalcedo.swaswa.ui.document.xlsx;

import io.joshuasalcedo.swaswa.html.PageScript;
import io.joshuasalcedo.swaswa.react.ReactElement;
import io.joshuasalcedo.swaswa.react.ReactListener;
import io.joshuasalcedo.swaswa.ui.Ui;
import java.nio.file.Path;
import java.util.List;
import java.util.function.Consumer;

/**
 * swaswa-ui's {@code XlsxEditor} (xlsx-viewer.tsx), a real React component, from Java: create it, set it, add it.
 * Generated by swaswa-react java-gen from its TypeScript props: do not edit.
 */
public final class UiXlsxEditor extends ReactElement<UiXlsxEditor> {

    /** A UiXlsxEditor. */
    public UiXlsxEditor() {
        super("XlsxEditor", false);
    }

    /** {@code src}. Where the workbook is: a URL, or a data: URL (how Java sends one). */
    public UiXlsxEditor setSrc(String value) {
        return prop("src", value);
    }

    public String getSrc() {
        return getProp("src", String.class);
    }

    /** {@code data}. The workbook's bytes, instead of src. */
    public UiXlsxEditor setDataProp(byte[] value) {
        return prop("data", value);
    }

    /** {@code data}, as a path. The workbook's bytes, instead of src. */
    public UiXlsxEditor setDataProp(Path value) {
        return prop("data", value);
    }

    /** {@code fileName}. The name it is shown and downloaded as (from src, unless given). */
    public UiXlsxEditor setFileName(String value) {
        return prop("fileName", value);
    }

    public String getFileName() {
        return getProp("fileName", String.class);
    }

    /** {@code showToolbar}. The zoom, search, download (and the editor's undo, redo, styles, save) bar. Shown unless false. */
    public UiXlsxEditor setShowToolbar(boolean value) {
        return prop("showToolbar", value);
    }

    public boolean isShowToolbar() {
        return Boolean.TRUE.equals(getProp("showToolbar", Boolean.class));
    }

    /** {@code height}. Its height (e.g. 480 or "60vh"); 520 unless given or set by className / style. */
    public UiXlsxEditor setHeight(String value) {
        return prop("height", value);
    }

    public String getHeight() {
        return getProp("height", String.class);
    }

    /** Told when it calls {@code onSave}, with what it calls it with. Save (the toolbar's button, Ctrl+S / ⌘S): the workbook's bytes as .xlsx, with its name. Without it, the toolbar offers a download of the edited copy only. */
    public UiXlsxEditor onSave(Consumer<byte[]> listener) {
        return onEvent("onSave", e -> listener.accept(e.payload(byte[].class)));
    }

    /** Told when it calls {@code onChange}. The workbook was edited (a cell, a style, a sheet): each change. */
    public UiXlsxEditor onChange(ReactListener listener) {
        return onEvent("onChange", listener);
    }

    /** {@code readOnly}. Shows it without letting it be edited (the formula bar stays, read-only). */
    public UiXlsxEditor setReadOnly(boolean value) {
        return prop("readOnly", value);
    }

    public boolean isReadOnly() {
        return Boolean.TRUE.equals(getProp("readOnly", Boolean.class));
    }

    @Override
    protected List<PageScript> libraries() {
        return List.of(Ui.bundle());
    }
}
